import { db } from "@/db";
import { messages, sessions } from "@/db/schema";
import { and, count, eq, gte, isNotNull, sql } from "drizzle-orm";

export async function getDashboardStats(userId: string) {
  // Calculate the date 30 days ago.
  const thirtyDaysAgo = new Date();
  thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 29);
  thirtyDaysAgo.setHours(0, 0, 0, 0);

  // 1. Total research sessions belonging to this user.
  const [sessionStats] = await db
    .select({
      total: count(),
    })
    .from(sessions)
    .where(eq(sessions.userId, userId));

  // 2. Total reports generated by this user.
  const [reportStats] = await db
    .select({
      total: count(),
    })
    .from(messages)
    .innerJoin(sessions, eq(messages.sessionId, sessions.id))
    .where(and(eq(sessions.userId, userId), isNotNull(messages.report)));

  // 3. Retrieve sources from this user's assistant messages.
  const sourceMessages = await db
    .select({
      sources: messages.sources,
    })
    .from(messages)
    .innerJoin(sessions, eq(messages.sessionId, sessions.id))
    .where(and(eq(sessions.userId, userId), eq(messages.role, "assistant")));

  const totalSources = sourceMessages.reduce((total, message) => {
    return (
      total + (Array.isArray(message.sources) ? message.sources.length : 0)
    );
  }, 0);

  // 4. Research activity over the last 30 days.
  const activity = await db
    .select({
      date: sql<string>`TO_CHAR(${messages.createdAt}, 'YYYY-MM-DD')`,
      total: count(),
    })
    .from(messages)
    .innerJoin(sessions, eq(messages.sessionId, sessions.id))
    .where(
      and(
        eq(sessions.userId, userId),
        eq(messages.role, "user"),
        gte(messages.createdAt, thirtyDaysAgo)
      )
    )
    .groupBy(sql`TO_CHAR(${messages.createdAt}, 'YYYY-MM-DD')`)
    .orderBy(sql`TO_CHAR(${messages.createdAt}, 'YYYY-MM-DD')`);

  return {
    totalSessions: sessionStats.total,
    totalReports: reportStats.total,
    totalSources,
    activity,
  };
}
